import{_ as o,c as r,a2 as a,o as p}from"./chunks/framework.DpbDeoNR.js";const i="/pub-blog/assets/image-20260129134551523.CZl_6gn_.png",s="/pub-blog/assets/image-20260129134524149.-X1LuI7w.png",e="/pub-blog/assets/image-20260129134759023.DNKSc-cx.png",n="/pub-blog/assets/image-20260129135155933.Cql7O1hL.png",l="/pub-blog/assets/image-20260129135013524.D30KVyFC.png",m="/pub-blog/assets/image-20260129135100998.DP7k5Kq-.png",g="/pub-blog/assets/image-20260129135556717.tXhVhq_D.png",c="/pub-blog/assets/image-20260129135720762.Bk5SxPQa.png",_="/pub-blog/assets/%E5%BE%AE%E4%BF%A1%E5%8F%B7%E5%92%8C%E4%BA%8C%E7%BB%B4%E7%A0%81.KtucpRsB.jpg",B=JSON.parse('{"title":"最强Kimi K2.5 真能做到一句话开发一个应用 - 3分钟简单上手体验","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/最强Kimi K2.5 真能做到一句话开发一个应用 - 3分钟简单上手体验/最强Kimi K2.5 真能做到一句话开发一个应用 - 3分钟简单上手体验.md","filePath":"AI人工智能/最强Kimi K2.5 真能做到一句话开发一个应用 - 3分钟简单上手体验/最强Kimi K2.5 真能做到一句话开发一个应用 - 3分钟简单上手体验.md","lastUpdated":1769666880000}'),h={name:"AI人工智能/最强Kimi K2.5 真能做到一句话开发一个应用 - 3分钟简单上手体验/最强Kimi K2.5 真能做到一句话开发一个应用 - 3分钟简单上手体验.md"};function b(K,t,d,u,k,f){return p(),r("div",null,t[0]||(t[0]=[a('<h1 id="最强kimi-k2-5-真能做到一句话开发一个应用-3分钟简单上手体验" tabindex="-1">最强Kimi K2.5 真能做到一句话开发一个应用 - 3分钟简单上手体验 <a class="header-anchor" href="#最强kimi-k2-5-真能做到一句话开发一个应用-3分钟简单上手体验" aria-label="Permalink to &quot;最强Kimi K2.5 真能做到一句话开发一个应用 - 3分钟简单上手体验&quot;">​</a></h1><blockquote><p><strong>万少：华为HDE、鸿蒙极客、个人独立开发者</strong></p><p>个人主页：<a href="https://blog.zbztb.cn/" target="_blank" rel="noreferrer">https://blog.zbztb.cn/</a></p><p><strong>2025年参与孵化了20+鸿蒙应用、技术文章300+、鸿蒙知识库用户500+、鸿蒙免费课程2套。</strong></p><p>如果你也喜欢交流AI和鸿蒙技术，欢迎扣我。</p></blockquote><h2 id="_1月27日" tabindex="-1">1月27日 <a class="header-anchor" href="#_1月27日" aria-label="Permalink to &quot;1月27日&quot;">​</a></h2><p>月之暗面 在1月27日 推出号称<strong>迄今为止最强大的开源模型</strong> 《<strong>Kimi K2.5</strong>》</p><p><img src="'+i+'" alt=""></p><p>Kimi K2.5 基于 <strong>Kimi K2</strong> 构建，通过约 <strong>15T</strong> 混合视觉和文本 <strong>token</strong> 的持续预训练。</p><p>作为原生多模态模型，K2.5 提供了最先进的编码和视觉能力，以及自导向的代理群范式。</p><p>对于复杂任务，<strong>Kimi K2.5 可以自导向一个最多包含 100 个子代理的代理群，执行跨越最多 1,500 个工具调用的并行工作流</strong>。</p><p>与单代理设置相比，<strong>这可将执行时间缩短高达 4.5 倍</strong>。</p><p>代理群由 Kimi K2.5 自动创建和编排，无需任何预定义的子代理或工作流。</p><hr><p>100多个子代理，这不就是一堆专家围着你转了吗？</p><p>想象一个场景:</p><p>你进到了饭店点一盘<strong>鱼香肉丝</strong>：</p><ol><li><strong>有农业专家帮你选择最好的食材</strong></li><li><strong>有营养专家帮你搭配最合适的食材比例</strong></li><li><strong>有大厨师帮你烹饪最美味的食物</strong></li><li><strong>有艺术家帮你做最精美的摆盘</strong></li><li><strong>有音乐家帮你在旁边奏乐</strong></li><li>。。。</li></ol><p>还有很多专家围绕你的需求去服务。</p><p><img src="'+s+'" alt=""></p><h2 id="能力对比" tabindex="-1">能力对比 <a class="header-anchor" href="#能力对比" aria-label="Permalink to &quot;能力对比&quot;">​</a></h2><p>Kimi K2.5 可通过 Kimi.com、Kimi App、API 和 Kimi Code 获取。</p><p>Kimi.com &amp; Kimi App 现在支持 4 种模式：K2.5 即时模式、K2.5 思考模式、K2.5 代理模式和 K2.5 代理群（Beta 版）。</p><p>代理群目前在 Kimi.com 上处于 Beta 测试阶段，高等级付费用户可免费使用。</p><p><img src="'+e+'" alt=""></p><p>可以看到和国外顶尖的大模型相比也是毫不逊色。</p><h2 id="如何体验" tabindex="-1">如何体验 <a class="header-anchor" href="#如何体验" aria-label="Permalink to &quot;如何体验&quot;">​</a></h2><p>大家如果想要简单体验一下，可以使用腾讯的<strong>CodeBuddy CN</strong>，它已经内置了K2.5模型，可以通过AI编辑器简单感受一下编程的能力。</p><blockquote><p><a href="https://copilot.tencent.com/promotion/?ref=vlt2x31eyhp8a1" target="_blank" rel="noreferrer">https://copilot.tencent.com/promotion/?ref=vlt2x31eyhp8a1</a></p></blockquote><p><img src="'+n+'" alt=""></p><p>如果想要感受 100个代理（牛马）给你服务的感觉，你可以在Kimi官网上去体验一下。</p><blockquote><p><a href="https://www.kimi.com/agent-swarm" target="_blank" rel="noreferrer">https://www.kimi.com/agent-swarm</a></p></blockquote><p><img src="'+l+'" alt=""></p><p>目前新业务营业大酬宾 ￥4.99 可以享受7天的使用。</p><p><img src="'+m+'" alt=""></p><h2 id="一句话生成应用" tabindex="-1">一句话生成应用 <a class="header-anchor" href="#一句话生成应用" aria-label="Permalink to &quot;一句话生成应用&quot;">​</a></h2><p>回到<strong>CodeBuddy CN</strong>编辑器内，打开对话框，输入以下提示词：</p><blockquote><p>帮我做一个单机版本的 HarmonyOS应用单机唯美风格，主题是 时光心情簿。</p><p>1首屏上是 4个tab，分别是首页-记录-统计-我的 1 首页是一个透明有边框的存钱罐，点击不同的心情图标可以往存钱罐里面存图标，图标下落要有动画效果，存钱罐在瓶子里也有有真实的碰撞效果</p><p>2 记录页面是一个可以根据日历来添加心情状态的页面，接受上传最多3章图片</p><p>3 统计使用好看的图标技术，可以实现按照年、月、日、不同的心情种类开始统计</p><p>4 我的 页面提供常见的一些功能，比如设置风格、字体大小、震动等等 所有页面设计都要有好看的过渡动画，一些页面也可以加入你找到的免费的背景图</p></blockquote><p><strong>CodeBuddy CN</strong>会帮我制定计划，确认无误后，开始干活。</p><p><img src="'+g+'" alt=""></p><h2 id="最终效果" tabindex="-1">最终效果 <a class="header-anchor" href="#最终效果" aria-label="Permalink to &quot;最终效果&quot;">​</a></h2><p><img src="'+c+'" alt=""></p><p>可以看到，<strong>UI 效果整体还是不错的</strong>，功能是还存在需要仔细调整的部分。</p><p>但是这个可是生成<strong>HarmonyOS 鸿蒙应用</strong>呀，</p><p>不是传统的安卓和 iOS，很多AI编辑器做鸿蒙开发还处在语法都不过关的时代！</p><hr><p>参考链接：<a href="https://www.kimi.com/blog/kimi-k2-5.html" target="_blank" rel="noreferrer">https://www.kimi.com/blog/kimi-k2-5.html</a></p><h2 id="关注我" tabindex="-1">关注我 <a class="header-anchor" href="#关注我" aria-label="Permalink to &quot;关注我&quot;">​</a></h2><p><strong>关注我</strong>，持续分享鸿蒙开发 + AI 提效的实战技巧。</p><p><img src="'+_+'" alt="img"></p>',47)]))}const w=o(h,[["render",b]]);export{B as __pageData,w as default};
